const { raiseListenerLimit } = require('./util/raise-listener-limit')
const path = require('path')
const os = require('os')
const yaml = require('js-yaml')
const { toMarkdownUrl } = require('../extension-utils/url-utils')
const { formatLlmsDirective } = require('../extension-utils/llms-utils')
const TurndownService = require('turndown')
const turndownPluginGfm = require('turndown-plugin-gfm')
const { gfm } = turndownPluginGfm

// Every doc-tools generator writes one comment line near the top of each file
// it produces, in this shape:
//
//   // This content is autogenerated. Do not edit manually. Generated by doc-tools (<generator>) from <source>. <how to change it>
//
// (cli-utils/generated-marker.js builds it.) Some files written before the
// version was dropped carry one after "doc-tools". Older files carry only the
// first two sentences. The twin's front matter reports what the marker says, so a
// reader (or an agent) can tell generated text from hand-written text on the
// same page and knows where the fix goes. The comment must open with the
// generated phrase, which every marker in the docs repos does ("This content
// is autogenerated", "AUTO-GENERATED FILE", "Generated by `doc-tools ...`"),
// so a prose comment such as "// Table generated by the build" is not one.
// "Generated by" counts only when doc-tools follows, so a hand-written
// "// Generated by running rpk cluster info, then edited" is not one either.
const GENERATED_MARKER_SCAN_LINES = 15
const GENERATED_MARKER_RE = /^\/\/\s*((?:this content is auto-?generated\b|auto-?generated\b|generated by\s+`?doc-tools\b).*)$/i
// "doc-tools (property-docs)", or with a version token: "doc-tools 5.55.0
// (rpk-docs)". A token that is not a version (the Python helpers once wrote
// "unknown") still yields the generator.
const MARKER_TOOL_RE = /doc-tools(?:\s+([^\s()]+))?\s*\(([^)]+)\)/i
// The source is named only right after the tool, or after "autogenerated"
// (connect's own banner), so a "from" later in a legacy banner's prose is not
// read as one.
const MARKER_SOURCE_RE = /(?:doc-tools(?:\s+[^\s()]+)?\s*\([^)]+\)|auto-?generated)\s+from\s+(.+?)(?:\.(?=\s|$)|$)/i
const INCLUDE_TARGET_RE = /^include::([^[\s{]+)\[/gm

/**
 * Read the generated-content marker from the first lines of an AsciiDoc file.
 * @param {Buffer|string} contents - The file's AsciiDoc source
 * @returns {{note: string, generator: (string|null), version: (string|null), source: (string|null)}|null}
 */
function readGeneratedMarker (contents) {
  if (!contents) return null
  const text = Buffer.isBuffer(contents) ? contents.toString('utf8') : String(contents)
  const lines = text.split(/\r?\n/, GENERATED_MARKER_SCAN_LINES)
  for (const line of lines) {
    const m = line.match(GENERATED_MARKER_RE)
    if (!m) continue
    const note = m[1].trim()
    const tool = note.match(MARKER_TOOL_RE)
    const generator = tool ? tool[2].trim() : null
    const token = tool && tool[1] ? tool[1].replace(/^v(?=\d)/i, '') : null
    const version = token && /^\d/.test(token) ? token : null
    const source = (note.match(MARKER_SOURCE_RE) || [])[1] || null
    return { note, generator, version, source: source ? source.trim() : null }
  }
  return null
}

/**
 * List the include targets in an AsciiDoc source. Targets that carry an
 * attribute reference cannot be resolved here and are skipped.
 * @param {Buffer|string} contents - The file's AsciiDoc source
 * @returns {string[]} Unique include targets, in order of first appearance
 */
function findIncludeTargets (contents) {
  if (!contents) return []
  const text = Buffer.isBuffer(contents) ? contents.toString('utf8') : String(contents)
  const targets = []
  for (const m of text.matchAll(INCLUDE_TARGET_RE)) {
    if (!targets.includes(m[1])) targets.push(m[1])
  }
  return targets
}

/**
 * Work out which text on a page is generated: the page itself, and any
 * include whose file carries the marker. Runs while the catalog still holds
 * AsciiDoc, before conversion.
 * @param {Object} page - Antora page file (src, contents)
 * @param {Object} contentCatalog - Antora content catalog
 * @returns {{page: (Object|null), includes: Object[]}}
 */
function collectGeneratedProvenance (page, contentCatalog) {
  const own = readGeneratedMarker(page.contents)
  const includes = []
  for (const target of findIncludeTargets(page.contents)) {
    let resource
    try {
      resource = contentCatalog.resolveResource(target, page.src, 'partial', ['partial', 'page', 'example'])
    } catch (err) {
      resource = null
    }
    if (!resource || !resource.contents) continue
    const marker = readGeneratedMarker(resource.contents)
    if (!marker) continue
    includes.push({ include: target, generator: marker.generator, version: marker.version, source: marker.source, note: marker.note })
  }
  return { page: own, includes }
}

/**
 * Decode HTML entities in a string
 * @param {string} str - String with potential HTML entities
 * @returns {string} Decoded string
 */
function decodeHtmlEntities (str) {
  if (!str || typeof str !== 'string') return str
  return str
    .replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(dec))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&apos;/g, "'")
}

/**
 * Converts AsciiDoc page attributes to YAML frontmatter
 * @param {Object} page - The page object with asciidoc attributes
 * @returns {string} YAML frontmatter string or empty string if no attributes
 */
function generateFrontmatter(page) {
  const frontmatter = {}

  // Add title (decode HTML entities from AsciiDoc processing)
  if (page.asciidoc?.doctitle) {
    frontmatter.title = decodeHtmlEntities(page.asciidoc.doctitle)
  }

  // Add navigation title if different from doctitle
  if (page.asciidoc?.navtitle && page.asciidoc.navtitle !== page.asciidoc?.doctitle) {
    frontmatter.navtitle = decodeHtmlEntities(page.asciidoc.navtitle)
  }

  // Get all page attributes
  const attrs = page.asciidoc?.attributes || {}

  // Allowlist of attributes to include in frontmatter
  // Explicitly opt-in to attributes that are useful for AI consumption
  const allowedAttributes = [
    'title',
    'navtitle',
    'description',
    // Note: 'categories' removed - it's a massive object (all Connect components)
    // that bloats frontmatter. Only include on pages that specifically need it.
    'page-component-name',
    'page-component-title',
    'page-component-version',
    'page-version',
    'page-relative-src-path',
    'page-edit-url',
    'page-topic-type',
    'personas',
    'docname',
    'page-beta',
    'page-beta-text',
    'page-is-nearing-eol',
    'page-is-past-eol',
    'page-eol-date',
    'page-git-created-date',
    'page-git-modified-date',
    // Generated-content provenance, from the markers generators write
    'page-generated-content',
    'page-autogenerated',
    'page-generated-by',
    'page-generated-from',
    'page-generated-sources',
    // Release that introduced the page's feature, and the product that
    // release belongs to. Generated Connect reference pages set them on
    // self-managed pages; the UI shows them as a "Since" badge.
    'page-introduced-in',
    'page-introduced-in-product',
    // Component-specific version attributes (from antora.yml)
    'latest-redpanda-tag', // Redpanda docker tag (e.g., v25.3.5)
    'latest-console-tag',
    'latest-operator-version',
    'latest-connect-version',
  ]

  // Blocklist of large data attributes that should never be in frontmatter
  // These are component-level data used by macros but shouldn't pollute markdown
  const blockedAttributes = [
    'categories',  // Massive nested object with all Connect components
    'connectCategoriesData',  // Raw Connect categories data
    'flatComponentsData',  // Flattened Connect component data
    'driverSupportData',  // SQL driver support matrix
    'cacheSupportData',  // Cache support matrix
    'csvData',  // Raw CSV data from generate-rp-connect-info
    'commercialNamesMap',  // Commercial names mapping
  ]

  // Add allowed page attributes to frontmatter
  Object.keys(attrs).forEach(key => {
    const value = attrs[key]

    // Skip blocked attributes (large data objects)
    if (blockedAttributes.includes(key)) return

    // Allow all learning-objective-* attributes (learning-objective-1, -2, -3, etc.)
    const isLearningObjective = key.startsWith('learning-objective-')

    // Only include attributes in our allowlist or learning objectives
    if (!allowedAttributes.includes(key) && !isLearningObjective) return

    // Only include page-beta-text if page-beta is true
    if (key === 'page-beta-text' && !attrs['page-beta']) {
      return
    }

    // Provenance travels as a JSON string in the attribute; the twin wants a list
    if (key === 'page-generated-sources') {
      try {
        frontmatter[key] = JSON.parse(value)
      } catch (err) {
        frontmatter[key] = value
      }
      return
    }
    if (key === 'page-autogenerated') {
      frontmatter[key] = value === '' || value === true || value === 'true'
      return
    }
    if (key === 'page-introduced-in' || key === 'page-introduced-in-product') {
      // Not boolean flags: an empty value (an unset attribute in a template)
      // means there is nothing to record.
      const text = String(value).trim()
      if (!text) return
      // A bare X.Y.Z, as the UI badge shows it.
      frontmatter[key] = key === 'page-introduced-in' ? text.replace(/^v/i, '').replace(/\.+$/, '') : text
      return
    }

    // Skip empty attributes (AsciiDoc boolean flags)
    if (value === '') {
      // Special handling for version fields - use actual version from page source
      if (key === 'page-version') {
        frontmatter[key] = page.src?.version || 'master'
        return
      }
      if (key === 'page-component-version') {
        frontmatter[key] = page.src?.version || 'master'
        return
      }
      // Preserve important boolean flags
      if (key.startsWith('page-')) {
        frontmatter[key] = true
      }
      return
    }

    // Include the attribute
    frontmatter[key] = value
  })

  // Transform EOL fields to be more user-friendly
  if (frontmatter['page-is-nearing-eol'] || frontmatter['page-is-past-eol']) {
    let eolStatus = 'supported'
    if (frontmatter['page-is-past-eol'] === 'true' || frontmatter['page-is-past-eol'] === true) {
      eolStatus = 'past end-of-life'
    } else if (frontmatter['page-is-nearing-eol'] === 'true' || frontmatter['page-is-nearing-eol'] === true) {
      eolStatus = 'nearing end-of-life'
    }
    frontmatter['support-status'] = eolStatus
    // Keep original fields for compatibility
  }

  // Transform beta fields to be more user-friendly
  if (frontmatter['page-beta'] === 'true' || frontmatter['page-beta'] === true) {
    let betaStatus = 'beta'
    if (frontmatter['page-beta-text']) {
      betaStatus = `beta - ${frontmatter['page-beta-text']}`
    }
    frontmatter['release-status'] = betaStatus
  }

  // Return empty string if no frontmatter
  if (Object.keys(frontmatter).length === 0) return ''

  // Convert to YAML format using js-yaml library for proper escaping
  let yamlContent = yaml.dump(frontmatter, {
    lineWidth: -1, // Disable line wrapping
    noRefs: true, // Disable anchors/aliases
    quotingType: '"', // Use double quotes
    forceQuotes: false, // Only quote when necessary
  })

  // Add helpful comments for EOL (end-of-life) fields
  // Find the first EOL-related field and add comment before it
  if (frontmatter['page-is-nearing-eol'] || frontmatter['page-is-past-eol'] || frontmatter['support-status']) {
    const eolFieldRegex = /^(page-is-nearing-eol:|page-is-past-eol:|support-status:)/m
    if (!yamlContent.includes('# EOL =')) {
      yamlContent = yamlContent.replace(
        eolFieldRegex,
        '# EOL = End-of-Life (support lifecycle status)\n$1'
      )
    }
  }

  // Add helpful comments for beta fields
  if (frontmatter['page-beta'] || frontmatter['release-status']) {
    const betaFieldRegex = /^(page-beta:|release-status:)/m
    if (!yamlContent.includes('# Beta release')) {
      yamlContent = yamlContent.replace(
        betaFieldRegex,
        '# Beta release status\n$1'
      )
    }
  }

  return `---\n${yamlContent}---\n\n`
}

// Default class the enterprise inline macro puts on its wrapping span. The
// macro lets a playbook override it via the enterprise-feature-role document
// attribute, so match on a substring rather than the exact value.
const ENTERPRISE_FEATURE_CLASS = 'enterprise-feature'

// Status words collected into the single trailing parenthetical.
const ENTERPRISE_STATUS = 'enterprise'
const BETA_STATUS = 'beta'

// Class the badge macro puts on a beta badge.
const BETA_BADGE_CLASS = 'badge--beta'

// Explicit textual marker for enterprise features in Markdown output.
const ENTERPRISE_MARKER = `(${ENTERPRISE_STATUS})`

/**
 * Format one parenthetical from the status words that apply to a feature.
 *
 * A beta enterprise feature carries two markers, and emitting them separately
 * reads as "Stretch Clusters (enterprise) (beta)". One list avoids the stutter.
 *
 * @param {string[]} statuses - Status words, in display order.
 * @returns {string} Parenthetical, or an empty string when there are none.
 */
function formatStatusMarker (statuses) {
  const words = statuses.filter(Boolean)
  return words.length ? `(${words.join(', ')})` : ''
}

function hasClass (node, className) {
  if (!node || node.nodeName !== 'SPAN') return false
  const classAttr = node.getAttribute?.('class') || node.className || ''
  return typeof classAttr === 'string' && classAttr.includes(className)
}

/**
 * The next sibling element, skipping the whitespace text nodes that sit between
 * the enterprise span and a badge that follows it.
 */
function nextElementSibling (node) {
  let sibling = node && node.nextSibling
  while (sibling && sibling.nodeType === 3 && !(sibling.textContent || '').trim()) {
    sibling = sibling.nextSibling
  }
  return sibling && sibling.nodeType === 1 ? sibling : null
}

/**
 * Turndown rules that keep the enterprise and beta signals in Markdown output.
 *
 * In HTML both signals are carried by things Turndown discards. The enterprise
 * badge is drawn by CSS from the span's class and explained by a title tooltip,
 * so `enterprise:Tiered Storage[]` would arrive in Markdown as the bare words
 * "Tiered Storage", indistinguishable from any other feature name. The beta
 * badge does survive, because its label keeps real bracketed text, but it lands
 * as a second parenthetical right after the first.
 *
 * These rules emit one trailing parenthetical instead, listing every status
 * that applies, and pass the span's already-converted inner Markdown through
 * untouched so a linked feature keeps its link:
 *
 *   [Stretch Clusters](../deploy/stretch-clusters.md) (enterprise, beta)
 *
 * The beta badge is a sibling of the enterprise span rather than a child. The
 * enterprise rule looks ahead for it and, when it finds one, emits no marker of
 * its own and hands the combined marker to the badge. Emitting it there rather
 * than on the enterprise span reuses the whitespace already between the two
 * elements, instead of suppressing the badge and leaving a doubled space.
 *
 * @returns {{enterpriseFeature: object, betaBadge: object}} Turndown rules,
 *   both of which must be registered.
 */
function createEnterpriseFeatureRules () {
  // Scoped per call so each converter tracks its own deferred markers.
  const deferredToBadge = new WeakSet()

  const enterpriseFeature = {
    filter: (node) => hasClass(node, ENTERPRISE_FEATURE_CLASS),
    replacement: (content, node) => {
      const inner = (content || '').trim()
      // An empty span carries no feature to mark.
      if (!inner) return ''
      // Nested or already-marked content must not collect a second marker.
      if (inner.toLowerCase().endsWith(ENTERPRISE_MARKER)) return inner

      const sibling = nextElementSibling(node)
      if (hasClass(sibling, BETA_BADGE_CLASS)) {
        // The badge renders "(enterprise, beta)" for both of us.
        deferredToBadge.add(sibling)
        return inner
      }
      return `${inner} ${ENTERPRISE_MARKER}`
    },
  }

  const betaBadge = {
    filter: (node) => hasClass(node, BETA_BADGE_CLASS),
    replacement: (content, node) =>
      deferredToBadge.has(node)
        ? formatStatusMarker([ENTERPRISE_STATUS, BETA_STATUS])
        : formatStatusMarker([BETA_STATUS]),
  }

  return { enterpriseFeature, betaBadge }
}

module.exports.createEnterpriseFeatureRules = createEnterpriseFeatureRules
module.exports.generateFrontmatter = generateFrontmatter
module.exports.formatStatusMarker = formatStatusMarker
module.exports.ENTERPRISE_MARKER = ENTERPRISE_MARKER
module.exports.readGeneratedMarker = readGeneratedMarker
module.exports.findIncludeTargets = findIncludeTargets
module.exports.collectGeneratedProvenance = collectGeneratedProvenance

module.exports.register = function () {
  raiseListenerLimit(this)
  const logger = this.getLogger('convert-to-markdown-extension')
  let playbook

  // Shared Turndown configuration
  const baseConfig = {
    headingStyle: 'atx',
    codeBlockStyle: 'fenced',
    bulletListMarker: '-',
    linkReferenceStyle: 'full',
  }

  // Factory: create a configured Turndown instance
  function createTurndownBase() {
    const td = new TurndownService(baseConfig)
    td.use(gfm)

    // Remove unwanted global elements (footers, modals, feedback, etc.)
    td.addRule('remove-unwanted', {
      filter: (node) => {
        if (!node || !node.getAttribute) return false

        const classAttr = (node.getAttribute('class') || '').toLowerCase()
        const idAttr = (node.getAttribute('id') || '').toLowerCase()
        const tag = node.nodeName.toLowerCase()

        // Remove by tag
        if (['script', 'style', 'footer', 'nav'].includes(tag)) return true

        // Remove tracking or hidden images
        if (
          tag === 'img' &&
          (classAttr.includes('tracking') ||
            idAttr.includes('scarf') ||
            node.getAttribute('role') === 'presentation' ||
            node.style?.display === 'none')
        ) {
          return true
        }

        // Remove by class or id
        const toRemove = [
          'thumbs',
          'back-to-top',
          'contributors-modal',
          'feedback-section',
          'feedback-toast',
          'pagination',
          'footer',
          'nav-expand',
          'banner-container',
          'markdown-dropdown',
          'version-selector',        // Version dropdown (not relevant for LLMs)
          'component-indicator',     // Component header bar
          'product-switcher',        // Product switcher dropdown
          'breadcrumb',              // Breadcrumb navigation
          'chat-panel',              // AI chat interface
          'kapa',                    // Kapa AI widget
        ]
        return toRemove.some(
          (x) => classAttr.includes(x) || idAttr.includes(x)
        )
      },
      replacement: () => '',
    })

    // Keep critical content blocks only
    td.keep(['div.openblock.tabs', 'article.doc'])
    return td
  }

  // Factory: create page-specific Turndown converter
  function createTurndownForPage(page) {
    const outerTurndown = createTurndownBase()
    const nestedTurndown = createTurndownBase()

    // Helper to add custom rules
    function addCustomRules(turndownInstance, isInner = false) {
      // Determine heading depth for tab conversion
      function findNearestHeadingLevel(el) {
        let current = el.previousElementSibling
        while (current) {
          if (/^H[1-6]$/i.test(current.nodeName))
            return parseInt(current.nodeName.substring(1))
          current = current.previousElementSibling
        }
        let parent = el.parentElement
        while (parent) {
          const headings = Array.from(
            parent.querySelectorAll('h1,h2,h3,h4,h5,h6')
          )
          if (headings.length > 0) {
            const last = headings[headings.length - 1]
            return parseInt(last.nodeName.substring(1))
          }
          parent = parent.parentElement
        }
        return 2
      }

      // Asciidoctor tab conversion
      turndownInstance.addRule('asciidoctor-tabs', {
        filter: (node) => {
          if (node.nodeName !== 'DIV') return false
          const classAttr = node.getAttribute?.('class') || node.className || ''
          return classAttr.includes('openblock') && classAttr.includes('tabs')
        },
        replacement: function (_, node) {
          function processTabGroup(group, parentHeadingLevel = null) {
            const contentDiv = group.querySelector('.content') || group
            const tabList = contentDiv.querySelectorAll('li.tab')
            if (!tabList.length) return ''

            const nearestLevel =
              parentHeadingLevel != null
                ? parentHeadingLevel + 1
                : findNearestHeadingLevel(group) + 1
            const tabHeadingLevel = Math.min(nearestLevel, 6)
            const headingPrefix = '#'.repeat(tabHeadingLevel)

            let markdown = ''
            tabList.forEach((tab) => {
              const title =
                tab.querySelector('p')?.textContent.trim() ||
                tab.textContent.trim()

              let panelId = tab.getAttribute('aria-controls')
              if (!panelId && tab.id) panelId = tab.id + '--panel'
              const panel = group.querySelector(`#${panelId}`)
              if (!panel) return

              const nestedTabs = panel.querySelectorAll('.openblock.tabs')
              let nestedMdCombined = ''
              nestedTabs.forEach((nested) => {
                nestedMdCombined +=
                  '\n' + processTabGroup(nested, tabHeadingLevel) + '\n'
                nested.remove()
              })

              const innerHtml = panel.innerHTML || ''
              let md = ''
              try {
                const converter = isInner ? nestedTurndown : turndownInstance
                md = converter.turndown(innerHtml)
              } catch (e) {
                logger.warn(`Turndown failed in nested tab: ${e.message}`)
              }

              markdown += `${headingPrefix} ${title}\n\n${md.trim()}\n${nestedMdCombined.trim()}\n\n`
            })

            return markdown.trim()
          }

          return '\n' + processTabGroup(node, null) + '\n'
        },
      })

      // Admonition block conversion
      turndownInstance.addRule('admonition', {
        filter: (node) =>
          node.nodeName === 'TABLE' &&
          node.querySelector('td.icon') &&
          node.querySelector('td.content'),
        replacement: function (_, node) {
          const iconCell = node.querySelector('td.icon')
          const contentCell = node.querySelector('td.content')
          if (!iconCell || !contentCell) return ''

          const iconEl = iconCell.querySelector('i')
          const classAttr = iconEl?.className || ''
          const match = classAttr.match(/icon-([a-z]+)/i)
          const type = match ? match[1].toUpperCase() : 'NOTE'

          const titleEl =
            node.querySelector('.title') ||
            contentCell.querySelector('.title') ||
            iconEl?.getAttribute('title')
          const customTitle =
            typeof titleEl === 'string'
              ? titleEl.trim()
              : titleEl?.textContent?.trim() || ''

          const emojiMap = {
            CAUTION: '⚠️',
            WARNING: '⚠️',
            TIP: '💡',
            NOTE: '📝',
            IMPORTANT: '❗',
          }
          const emoji = emojiMap[type] || '📘'

          const innerHtml = contentCell.innerHTML || ''
          let innerMd = ''
          try {
            const converter = isInner ? nestedTurndown : turndownInstance
            innerMd = converter.turndown(innerHtml).trim()
          } catch (e) {
            logger.warn(`Turndown failed in admonition: ${e.message}`)
          }

          const titleLower = customTitle.toLowerCase()
          const typeLower = type.toLowerCase()
          const header =
            customTitle && titleLower !== typeLower
              ? `${emoji} **${type}: ${customTitle}**`
              : `${emoji} **${type}**`

          const quoted = innerMd
            .split('\n')
            .map((line) => (line.startsWith('>') ? line : `> ${line}`))
            .join('\n')

          return `\n> ${header}\n>\n${quoted}\n`
        },
      })

      // Markdown table conversion
      // Keep the enterprise-license signal, which is otherwise CSS-only.
      const enterpriseRules = createEnterpriseFeatureRules()
      turndownInstance.addRule('enterprise-feature', enterpriseRules.enterpriseFeature)
      turndownInstance.addRule('beta-badge', enterpriseRules.betaBadge)

      turndownInstance.addRule('tables', {
        filter: (node) => {
          if (node.nodeName !== 'TABLE') return false
          if (node.querySelector('td.icon') && node.querySelector('td.content'))
            return false
          return true
        },
        replacement: function (content, node) {
          const rows = Array.from(node.querySelectorAll('tr'))
          if (!rows.length) return content
          const tableRows = []
          rows.forEach((row, index) => {
            const cells = Array.from(row.querySelectorAll('th, td'))
            const cellContents = cells.map((cell) =>
              (cell.textContent || '').trim().replace(/\s+/g, ' ')
            )
            if (!cellContents.length) return
            const rowLine = '| ' + cellContents.join(' | ') + ' |'
            tableRows.push(rowLine)
            if (index === 0) {
              const separator =
                '| ' + cellContents.map(() => '---').join(' | ') + ' |'
              tableRows.push(separator)
            }
          })
          return '\n' + tableRows.join('\n') + '\n'
        },
      })
    }

    addCustomRules(outerTurndown, false)
    addCustomRules(nestedTurndown, true)
    return outerTurndown
  }

  // Record which text on each page is generated, while the catalog still
  // holds AsciiDoc: the page's own marker, and the marker on every include it
  // resolves to. An extension that generates pages at build time sets
  // page.generatedProvenance itself, and that wins.
  this.on('contentClassified', ({ contentCatalog }) => {
    const pages = contentCatalog.findBy({ family: 'page' })
    let marked = 0
    for (const page of pages) {
      if (page.generatedProvenance) {
        marked++
        continue
      }
      const provenance = collectGeneratedProvenance(page, contentCatalog)
      if (provenance.page || provenance.includes.length) {
        page.generatedProvenance = provenance
        marked++
      }
    }
    logger.info(`Recorded generated-content provenance on ${marked} of ${pages.length} pages`)
  })

  // Add marker attribute before UI rendering so templates can detect markdown availability
  this.on('documentsConverted', ({ contentCatalog }) => {
    const pages = contentCatalog.findBy({ family: 'page' })
    logger.info(`Marking ${pages.length} pages as having markdown equivalents...`)

    pages.forEach((page) => {
      // Ensure attributes object exists
      if (!page.asciidoc) page.asciidoc = {}
      if (!page.asciidoc.attributes) page.asciidoc.attributes = {}

      // Add marker that UI templates can check
      page.asciidoc.attributes['page-has-markdown'] = ''

      // Provenance as page attributes, so the twin's front matter and the UI
      // templates can both read it. page-generated-content is set on every
      // page, so "none" is a statement and not an absence.
      const provenance = page.generatedProvenance
      let generatedContent = 'none'
      if (provenance?.page) {
        generatedContent = 'all'
        page.asciidoc.attributes['page-autogenerated'] = 'true'
        const { generator, version, source } = provenance.page
        if (generator) {
          page.asciidoc.attributes['page-generated-by'] = `doc-tools${version ? ` ${version}` : ''} (${generator})`
        }
        // Only a named source: a legacy banner has none, and its prose is
        // not one.
        if (source) page.asciidoc.attributes['page-generated-from'] = source
      } else if (provenance?.includes?.length) {
        generatedContent = 'partial'
      }
      if (provenance?.includes?.length) {
        page.asciidoc.attributes['page-generated-sources'] = JSON.stringify(
          provenance.includes.map(({ include, generator, version, source }) => ({ include, generator, version, source }))
        )
      }
      page.asciidoc.attributes['page-generated-content'] = generatedContent
    })
  })

  // Conversion pipeline
  this.on('pagesComposed', async ({ playbook: pb, contentCatalog }) => {
    playbook = pb
    const siteUrl = playbook.site?.url || ''
    const pages = contentCatalog.getPages()
    logger.info(
      `Converting ${pages.length} pages to Markdown${
        siteUrl ? ` (site.url=${siteUrl})` : ''
      }...`
    )

    const concurrency = Math.max(2, Math.floor(os.cpus().length / 2))
    const queue = [...pages]
    let convertedCount = 0

    async function processQueue() {
      while (queue.length) {
        const page = queue.shift()
        if (!page?.contents) continue

        try {
          const html = page.contents.toString().trim()
          if (!html) continue

          // Extract only the <article class="doc"> portion
          const match = html.match(
            /<article[^>]*class=["'][^"']*\bdoc\b[^"']*["'][^>]*>([\s\S]*?)<\/article>/i
          )
          if (!match || !match[1]) {
            logger.info(`No <article class="doc"> found for ${page.src?.path}`)
            continue
          }
          const articleHtml = match[1]

          // Convert with Turndown
          const td = createTurndownForPage(page)
          let markdown = td.turndown(articleHtml).trim()

          // Canonical source link
          let canonicalUrl = ''
          try {
            if (siteUrl && page.pub?.url) {
              const baseUrl = new URL(page.pub.url, siteUrl)
              // Convert HTML URL to markdown URL using shared utility
              baseUrl.pathname = toMarkdownUrl(baseUrl.pathname)
              canonicalUrl = baseUrl.toString()
            }
          } catch (e) {
            logger.debug(
              `Failed to build canonical URL for ${page.src?.path}: ${e.message}`
            )
          }

          // Remove escaped underscores from headings (TurndownService escapes them unnecessarily)
          markdown = markdown.replace(/^(#{1,6}\s+.+)$/gm, (heading) => {
            return heading.replace(/\\_/g, '_')
          })

          // Skip directive for field-only pages (marked by generate-fields-only-pages extension)
          const isFieldOnlyPage = page.isFieldOnlyPage === true

          // Field-only pages: basic markdown only, no frontmatter, no directive, no source comments
          if (isFieldOnlyPage) {
            // Strip anchor links from headings: [](#anchor-id)heading → heading
            markdown = markdown.replace(/\[]\(#[^)]+\)/g, '')

            // Just use the markdown as-is with basic cleanup
            markdown = markdown.trim()
          } else {
            // Regular pages: full treatment with frontmatter and directive
            // Generate YAML frontmatter from AsciiDoc attributes
            const frontmatter = generateFrontmatter(page)
            if (frontmatter) {
              logger.debug(`Generated frontmatter for ${page.src?.path}`)
            }

            // Extract H1 heading if present (only at document start)
            const h1Match = markdown.match(/^(#\s+.+?)(\n|$)/)
            let h1Heading = ''
            let restOfMarkdown = markdown

            if (h1Match) {
              h1Heading = h1Match[0]
              restOfMarkdown = markdown.substring(h1Match[0].length).trimStart()
            }

            // Structure: H1 → llms.txt directive (blockquote) → frontmatter → source → content
            // The directive must appear near the top for agent-friendly docs spec compliance
            if (canonicalUrl) {
              const componentName = page.src?.component || '';
              // Use markdown blockquote format for the directive (visible, can be hidden with CSS)
              const llmsDirective = formatLlmsDirective(componentName);

              markdown = `${h1Heading}\n${llmsDirective}\n\n${frontmatter}<!-- Source: ${canonicalUrl} -->\n\n${restOfMarkdown}`
            } else if (frontmatter) {
              // If no canonical URL but we have frontmatter, still add directive after H1
              const llmsDirective = formatLlmsDirective();
              markdown = `${h1Heading}\n${llmsDirective}\n\n${frontmatter}${restOfMarkdown}`
            }
          }

          // Convert relative URLs to absolute URLs (after directive is added)
          if (siteUrl && page.pub?.url) {
            try {
              const baseUrl = new URL(siteUrl)
              const pageUrl = new URL(page.pub.url, baseUrl)

              // Convert absolute paths: [text](/path) → [text](https://domain/path)
              markdown = markdown.replace(/\[([^\]]+)\]\(\/([^)]+)\)/g, (match, text, path) => {
                try {
                  const fullUrl = new URL('/' + path, baseUrl).toString()
                  return `[${text}](${fullUrl})`
                } catch (e) {
                  return match // Keep original if URL construction fails
                }
              })

              // Convert relative paths: [text](../../path) → [text](https://domain/resolved/path)
              markdown = markdown.replace(/\[([^\]]+)\]\((\.\.\/[^)]+)\)/g, (match, text, relativePath) => {
                try {
                  // Resolve relative path against the current page URL
                  const fullUrl = new URL(relativePath, pageUrl).toString()
                  return `[${text}](${fullUrl})`
                } catch (e) {
                  return match // Keep original if URL construction fails
                }
              })
            } catch (e) {
              logger.debug(`Failed to resolve relative URLs for ${page.src?.path}: ${e.message}`)
            }
          }

          // Clean up unnecessary whitespace
          if (markdown) {
            // Remove excessive blank lines (more than 2 consecutive newlines)
            markdown = markdown.replace(/\n{3,}/g, '\n\n')
            // Remove trailing whitespace from lines
            markdown = markdown.replace(/[ \t]+$/gm, '')
            // Remove leading/trailing whitespace from the entire document
            markdown = markdown.trim()
          }

          if (markdown) {
            page.markdownContents = Buffer.from(markdown, 'utf8')
            convertedCount++
          }
        } catch (err) {
          logger.error(
            `Error converting ${page.src?.path || 'unknown'}: ${err.message}`
          )
          logger.debug(err.stack)
        }
      }
    }

    const workers = Array.from({ length: concurrency }, processQueue)
    await Promise.all(workers)
    logger.info(`Converted ${convertedCount} Markdown files.`)
  })

  // Add Markdown files to site catalog
  this.on('beforePublish', ({ siteCatalog, contentCatalog }) => {
    const pages = contentCatalog.getPages((p) => p.markdownContents)
    if (!pages.length) {
      logger.info('No Markdown files to publish.')
      return
    }
    logger.info(`Adding ${pages.length} Markdown files to site catalog...`)
    for (const page of pages) {
      const htmlOut = page.out?.path
      if (!htmlOut) continue

      // Convert HTML path to markdown path using shared utility
      const mdOutPath = toMarkdownUrl(htmlOut)

      siteCatalog.addFile({
        contents: page.markdownContents,
        out: { path: mdOutPath },
      })
      logger.debug(`Added Markdown: ${mdOutPath}`)
    }
  })
}
